import os
import ast
import requests
import unittest

from helper_func import make_results_url

class TestSQRFactGeneration(unittest.TestCase):

    def setUp(self):

        self.apikey = os.environ.get("API_KEY", "thisisatestkey")
        self.url = os.environ.get("TEST_URL", "http://127.0.0.1:5000/")
        self.ringid = "20e114c2-ef05-490c-bdd8-f6f271a6733f"
        self.versionid = "1"
        self.headers ={
            "x-api-key": self.apikey
        }
        self.maxDiff = None

    def test_sum_amount_one_per_plan(self):
        sqr_plan = {
            "|1|": "(retrieve_entity Contribution)",
            "|2|": "(retrieve_attribute |1| amount)",
            "|3|": "(sum |2|)",
            "|4|": "(collect |3|)",
            "|5|": "(return |4|)"
        }

        expected_results = ["The total contribution amount is 3745502.3 dollars."]

        urllink = make_results_url(self.url, self.ringid, self.versionid, None, "unittest_fact_gen_one_per_plan", {})
        resp = requests.get(urllink, headers=self.headers, json=sqr_plan)
        results = ast.literal_eval(resp.content.decode('utf-8'))
        self.assertListEqual(expected_results, results)

